import copy,io,json,tempfile,unittest
from pathlib import Path
from unittest.mock import patch
import engine
from output_contract import generation_payload,normalize,parse,schema
from quality import inspect_messages
from revalidation import refresh_context
from evidence_sources import candidate_spans
from source_review import audit
from test_judgment_calibration import local_review
from work.materials_split.compat_saved import adapt_saved
ROOT=Path(__file__).resolve().parents[1]
PLAN=json.loads((ROOT/'outputs/materials_split_v0.21.0_2026-11-05/PLAN.json').read_text())
OLD=ROOT/'outputs/judgment_calibration_v0.20.0_2026-11-05'

def saved(identity):
    ledger=json.loads((OLD/'CALLS.json').read_text());return json.loads((OLD/next(r['record']for r in ledger['results']if r['case_id']==identity)).read_text())

class MaterialsSplitTests(unittest.TestCase):
    def setUp(self):self.brand=engine.brand_data()
    def context(self,identity='J01',background=None,chat=None):
        c=copy.deepcopy(next(c for c in PLAN['cases']if c['case_id']==identity));v=c['input']
        if background is not None:v['client_info']=background
        if chat is not None:v['conversation']=chat
        r=dict(input=v,confirmed_context=engine.prepare_context(v),customer_context=c['customer_context']);return v,refresh_context(r,self.brand)

    def test_internal_facts_not_in_user_message_or_tool_schema(self):
        for case in PLAN['cases']:
            bodies=[]
            def model(config,body,audit):bodies.append(copy.deepcopy(body));raise engine.GenerationError('local_probe','本地材料探针')
            with tempfile.TemporaryDirectory()as temp,patch('engine.model_call',side_effect=model):r=engine.generate(dict(input=case['input']),engine.RunStore(temp),engine.Config('https://api.deepseek.com','fake','fake'),customer_context=case['customer_context'])
            raw=engine.json_text(bodies[0])
            for term in ['不称为超轻','未提供，取决于','不能断言有或没有','loaded_comfort','loaded_weight_g','relevant_unknown','## 3. 商品目录']:self.assertNotIn(term,raw)
            self.assertIn('brand_snapshot',r);self.assertIn('product_evidence_snapshot',r)
            if case['case_id']=='J01':self.assertEqual(len(r['generation_materials']['internal_validation']['facts']),3)

    def test_water_subtotal_has_original_source_and_is_not_full_load(self):
        v,p=self.context();row=p['load_reference']['records'][0]
        self.assertEqual((row['empty_weight_g'],row['water_weight_g'],row['subtotal_g']),(750,500,1250))
        self.assertEqual(row['parent_source_ids'],['product.P01.empty_weight_g','background.client_info'])
        source=next(r for r in p['evidence_sources']['sources']if r['id']==row['id']);self.assertEqual(source['kind'],'derived_load')
        self.assertIn('水瓶',source['excluded_components']);self.assertIn('computed.load.P01',[r['source_id']for r in p['task_materials']['generation_input']['facts']])
        for bg,total in [('平时带350毫升的水和A4资料。',1100),('每天带一瓶0.5升水。',1250),('每天带两瓶500毫升水。',1750)]:
            _,p=self.context(background=bg);self.assertEqual(p['load_reference']['records'][0]['subtotal_g'],total)
        for bg in ['平时带一瓶水和A4资料。','带一个容量500毫升的水瓶，装多少不固定。','以前带过500毫升水，这次不带水。']:
            _,p=self.context(background=bg);self.assertEqual(p['load_reference']['records'],[])

    def test_correct_subtotal_passes_and_wrong_sum_or_complete_total_still_blocked(self):
        v,p=self.context()
        for text in ['空包750克，水约500克，两项小计约1.25公斤，另加瓶子和资料。','750克空包加500克水，合计约1250克，还要加瓶子和资料。','光包和水就约1.25公斤，再加瓶子和资料，步行一刻钟日常可以，也可试背。','算上瓶子和资料，总重会超过1.25公斤。']:
            self.assertFalse(inspect_messages([text],self.brand['products'],focus_ids=['P01'],context=dict(value=v,prepared=p)),text)
        for text,code in [('水约600克。','wrong_load_calculation'),('两项小计约1.35公斤，来店可试背。','wrong_load_calculation'),('总重至少2公斤。','wrong_load_calculation'),('装好后总重约1.25公斤。','partial_load_as_total')]:
            self.assertIn(code,[e['code']for e in inspect_messages([text],self.brand['products'],focus_ids=['P01'],context=dict(value=v,prepared=p))])
            messages=[text,'空包约750克，日常通勤可以。','来店也可以装好常带物品试背。'];p['candidate_spans']=candidate_spans(messages)
            q=local_review(dict(candidate_messages=messages,confirmed_context=p,evidence_sources=p['evidence_sources']))
            self.assertIn('reviewer_missed_load_calculation',[e['code']for e in audit(q,dict(messages=messages),p,self.brand['products'],['P01'])])

    def test_price_concern_uses_brand_quote_and_low_key_preference_uses_one_design_fact(self):
        for chat in ['客户：一万四比我预想的高，只带手机钥匙合适吗？','客户：这笔钱超出预期了，平时只带手机，适合吗？']:
            _,p=self.context('J02',chat=chat);facts=p['task_materials']['generation_input']['facts'];ids={r['source_id']for r in facts}
            self.assertEqual(ids,{'product.P02.price','product.P02.capacity','policy.2'})
            self.assertEqual(next(r['text']for r in facts if r['source_id']=='product.P02.price'),'12,800元')
            self.assertIn('小尺寸压印',next(r['text']for r in facts if r['source_id']=='policy.2'))
            for word in ['折扣','水杯','雨伞','维修','电脑']:self.assertNotIn(word,engine.json_text(facts))

    def test_target_metadata_compatibility_is_narrow_and_preserves_raw(self):
        old=saved('J01');wire=parse(old['raw_output']);original=copy.deepcopy(wire)
        adapted,log=generation_payload(wire,old['parameters']['tools'][0]['function']['parameters'])
        self.assertEqual(wire,original);self.assertFalse(log['model_target_adopted']);self.assertEqual(log['scope_authority'],'user_request_only');self.assertEqual([adapted['messages']['reply_'+str(i)]for i in range(1,4)],old['diagnostic_candidates'])
        for index in range(3):
            value=copy.deepcopy(wire);value['messages']['target_index']=index;self.assertIsNotNone(generation_payload(value,schema('generation'))[1])
        for change in ['missing','fourth','unknown','root','wrong_type','other_extra','wrong_target']:
            value=copy.deepcopy(wire)
            if change=='missing':del value['messages']['reply_2']
            if change=='fourth':value['messages']['reply_4']='第四条'
            if change=='unknown':value['messages']['mystery']=0
            if change=='root':value['target_index']=value['messages'].pop('target_index')
            if change=='wrong_type':value['messages']['reply_1']=[]
            if change=='other_extra':value['messages']['client_state_note']=''
            if change=='wrong_target':value['messages']['target_index']='请修改第一条'
            with self.subTest(change=change),self.assertRaises(ValueError):generation_payload(value,schema('generation'))
        with self.assertRaises(ValueError):parse(old['raw_output'].replace('"target_index": 0','"target_index": 0, "target_index": 1'))

    def test_saved_real_review_and_all_three_texts_revalidate_without_model(self):
        original=saved('J01');before=copy.deepcopy(original)
        with patch('engine.model_call',side_effect=AssertionError('no model')):record=adapt_saved(original)
        self.assertEqual(record['status'],'success',record.get('error'));self.assertEqual(original,before);self.assertEqual(record['quality_review']['parsed_output'],original['quality_review']['parsed_output'])
        broken=copy.deepcopy(original);broken['raw_output']=broken['raw_output'].replace('750 g','650 g');broken['parsed_provider_output']=parse(broken['raw_output'])
        record=adapt_saved(broken);self.assertEqual(record['status'],'error');self.assertEqual(record['error']['code'],'policy_check')

    def test_model_target_never_overrides_user_revision_scope(self):
        parent=saved('J02');config=engine.Config('https://api.deepseek.com','deepseek-flash','fake',2)
        for out_of_scope in [False,True]:
            with tempfile.TemporaryDirectory()as temp:
                store=engine.RunStore(temp);store.save(parent);messages=parent['result']['messages'][:];messages[1]='轻行肩包是12,800元，日常只带手机和钥匙合适。'
                if out_of_scope:messages[0]='轻行肩包12,800元，日常手机钥匙能放下。'
                wire=dict(status='ready',client_state='comparing',messages={**dict(zip(('reply_1','reply_2','reply_3'),messages)), 'target_index':0},advisor_note='',missing_information=[])
                response=io.BytesIO(json.dumps(dict(choices=[dict(finish_reason='tool_calls',message=dict(content=None,tool_calls=[dict(function=dict(name='return_replies',arguments=json.dumps(wire,ensure_ascii=False)))]))])).encode());response.headers={}
                with patch('urllib.request.OpenerDirector.open',return_value=response),patch('engine.review_output',return_value={})as review:
                    record=engine.generate(dict(input=parent['input'],parent_run_id=parent['run_id'],target_index=1,advisor_request='这条更简短一点'),store,config,customer_context=parent['customer_context'])
                self.assertEqual(record['target_index'],1);self.assertFalse(record['output_compatibility']['model_target_adopted'])
                if out_of_scope:self.assertEqual(record['error']['code'],'revision_scope');review.assert_not_called()
                else:self.assertEqual(record['status'],'success',record.get('error'));review.assert_called_once()
